import{_ as e,o as a,c as r,a3 as l}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"Start with a template","description":"Create a Space from a ready-made template.","frontmatter":{"title":"Start with a template","description":"Create a Space from a ready-made template."},"headers":[],"relativePath":"en/erste-schritte/vorlagen.md","filePath":"en/erste-schritte/vorlagen.md","lastUpdated":1788108473000}'),s={name:"en/erste-schritte/vorlagen.md"};function o(i,t,n,d,p,h){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="start-with-a-template" tabindex="-1">Start with a template <a class="header-anchor" href="#start-with-a-template" aria-label="Permalink to &quot;Start with a template&quot;">​</a></h1><p>Under the Space overview you&#39;ll find <em>Or start with a template</em>. A template creates a ready-made Space — with Grids, Views, and, depending on the template, Forms, Flows, and Pages as well.</p><h2 id="why-use-a-template" tabindex="-1">Why use a template <a class="header-anchor" href="#why-use-a-template" aria-label="Permalink to &quot;Why use a template&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Also useful as a learning tool</p><p>A template shows you what a well-thought-out setup looks like: how Grids are linked, which Views make sense, how a Flow is structured.</p><p>Even if you end up building something of your own, it&#39;s worth creating a matching template once and taking it apart. That&#39;s faster than reading any guide.</p></div><h2 id="using-a-template" tabindex="-1">Using a template <a class="header-anchor" href="#using-a-template" aria-label="Permalink to &quot;Using a template&quot;">​</a></h2><ol><li>Open the Space overview.</li><li>Under <em>Or start with a template</em>, choose a template.</li><li>Follow the setup.</li></ol><p>This creates a <strong>new Space</strong>. Existing Spaces stay untouched.</p><h2 id="plan-requirements" tabindex="-1">Plan requirements <a class="header-anchor" href="#plan-requirements" aria-label="Permalink to &quot;Plan requirements&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Some templates need a higher plan</p><blockquote><p><em>This template requires at least a &quot;{plan}&quot; plan</em></p></blockquote><p>That&#39;s because templates can use plan-gated features — multiple flows, Pro steps, advanced form settings.</p></div><div class="warning custom-block"><p class="custom-block-title">A template can become unusable after the trial period</p><blockquote><p><strong>Trial period completed</strong></p><p><em>You have completed the trial period for this template. To keep using this template, please upgrade to a higher plan.</em></p></blockquote><p>So check <strong>before</strong> going live which plan a template requires — and whether you&#39;re willing to subscribe to it after the trial ends.</p><p>Remaining trial days are shown in the <a href="/en/spaces/einstellungen">Space settings</a>.</p></div><h2 id="after-creating-it" tabindex="-1">After creating it <a class="header-anchor" href="#after-creating-it" aria-label="Permalink to &quot;After creating it&quot;">​</a></h2><p>A template is a starting point, not a finished product. You&#39;ll typically adjust:</p><table tabindex="0"><thead><tr><th>Area</th><th>Typical adjustment</th></tr></thead><tbody><tr><td><strong>Fields</strong></td><td>Add your own fields, remove ones you don&#39;t need</td></tr><tr><td><strong>Select options</strong></td><td>Adapt to your own terminology</td></tr><tr><td><strong>Forms</strong></td><td>Text, colors, logo</td></tr><tr><td><strong>Flows</strong></td><td>Check email text and recipients</td></tr><tr><td><strong>Views</strong></td><td>Adjust filters to your own workflow</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Check flows from templates before going live</p><p>A template can include flows that send emails. Go through them <strong>before</strong> you share the first form:</p><ul><li>Who does the email go to? Is there still a placeholder address?</li><li>Does the text fit?</li><li>What trigger is set?</li></ul><p>Take a look at the <a href="/en/flows/was-ist-ein-flow">flow list</a> of the new Space for this.</p></div><div class="tip custom-block"><p class="custom-block-title">Check external links</p><p>Also check the <a href="/en/zusammenarbeit/externe-links">links overview</a> of the Space. If the template already includes published forms or portals, they may be reachable immediately.</p></div><h2 id="template-or-build-it-yourself" tabindex="-1">Template or build it yourself? <a class="header-anchor" href="#template-or-build-it-yourself" aria-label="Permalink to &quot;Template or build it yourself?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Recommendation</th></tr></thead><tbody><tr><td>The use case fits a template well</td><td><strong>Template</strong></td></tr><tr><td>You want to get to know ApptiveGrid</td><td><strong>Template</strong> — then take it apart</td></tr><tr><td>You have precise ideas of your own</td><td><strong>Build it yourself</strong></td></tr><tr><td>The template needs a plan you don&#39;t want</td><td><strong>Build it yourself</strong></td></tr><tr><td>You just need a simple form</td><td><strong>Build it yourself</strong> — faster than any template</td></tr></tbody></table><p>→ <a href="/en/erste-schritte/schnellstart">Your first app in 15 minutes</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/spaces/space-anlegen">Create a Space</a></li><li><a href="/en/erste-schritte/schnellstart">Your first app in 15 minutes</a></li><li><a href="/en/zusammenarbeit/externe-links">External links at a glance</a> — templates can already contain links</li></ul>',20)])])}const u=e(s,[["render",o]]);export{m as __pageData,u as default};
